import { Static } from '../../Static';

// The markdown subset a chat message carries, rendered to HTML. Text is
// escaped first, so a message can never inject markup; only the subset's
// own constructs become tags: headings, paragraphs, line breaks, bold,
// italic, links, images, code spans, fenced code (with its language kept
// on the block for the highlighter), lists, quotes, rules, and a media
// link alone on its line (YouTube, a video file) as an embed.
class $Markdown {
  static readonly YOUTUBE = /^(?:https?:\/\/)?(?:www\.|m\.)?(?:youtube\.com\/(?:watch\?(?:.*&)?v=|shorts\/|embed\/)|youtu\.be\/)([A-Za-z0-9_-]{11})(?:[?&#][^\s]*)?$/;
  static readonly VIDEO_FILE = /^https?:\/\/[^\s<>"']+\.(?:mp4|webm|mov)(?:\?[^\s<>"']*)?$/i;

  static youtubeId(text: string): string | null {
    const match = this.YOUTUBE.exec(text.trim());
    return match ? match[1] : null;
  }

  static isVideoUrl(text: string): boolean {
    return this.VIDEO_FILE.test(text.trim());
  }

  static embed(text: string): string | null {
    const id = this.youtubeId(text);
    if (id)
      return `<div class="chat-embed"><iframe src="https://www.youtube-nocookie.com/embed/${id}" title="YouTube video" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowfullscreen loading="lazy"></iframe></div>`;
    if (this.isVideoUrl(text)) return `<video class="chat-video" controls preload="metadata" src="${this.escape(text.trim())}"></video>`;
    return null;
  }

  static escape(text: string): string {
    return text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  }

  /** inline constructs inside one already-escaped line */
  static inline(text: string): string {
    return text
      .replace(/`([^`]+)`/g, '<code>$1</code>')
      .replace(/!\[([^\]]*)\]\(([^)\s]+)\)/g, '<img alt="$1" src="$2" loading="lazy">')
      .replace(/\[([^\]]+)\]\(([^)\s]+)\)/g, '<a href="$2" target="_blank" rel="noreferrer">$1</a>')
      .replace(/(\*\*|__)(.+?)\1/g, '<strong>$2</strong>')
      .replace(/(^|[^*\w])[*_]([^*_\n]+)[*_](?=[^*\w]|$)/g, '$1<em>$2</em>')
      .replace(/(^|[^"'>=])(https?:\/\/[^\s<]+)/g, '$1<a href="$2" target="_blank" rel="noreferrer">$2</a>');
  }

  /** a fenced block: escaped code with its language on the element for the highlighter */
  static fence(code: string, language: string): string {
    const lang = language.replace(/[^a-z0-9+#-]/gi, '').toLowerCase();
    return `<pre class="chat-code" data-lang="${lang}"><code>${code}</code></pre>`;
  }

  static render(markdown: string): string {
    const lines = this.escape(markdown.replace(/\r\n/g, '\n')).split('\n');
    const html: string[] = [];
    let paragraph: string[] = [];
    let list: { ordered: boolean; items: string[] } | null = null;
    let fence: { language: string; lines: string[] } | null = null;
    const flushParagraph = () => {
      if (paragraph.length) html.push(`<p>${paragraph.map((line) => this.inline(line)).join('<br>')}</p>`);
      paragraph = [];
    };
    const flushList = () => {
      if (list) {
        const tag = list.ordered ? 'ol' : 'ul';
        html.push(`<${tag}>${list.items.map((item) => `<li>${this.inline(item)}</li>`).join('')}</${tag}>`);
      }
      list = null;
    };
    for (const line of lines) {
      if (fence) {
        if (/^```/.test(line)) {
          html.push(this.fence(fence.lines.join('\n'), fence.language));
          fence = null;
        } else fence.lines.push(line);
        continue;
      }
      const opening = /^```\s*([\w+#-]*)/.exec(line);
      if (opening) {
        flushParagraph();
        flushList();
        fence = { language: opening[1] ?? '', lines: [] };
        continue;
      }
      const heading = /^(#{1,6})\s+(.+)$/.exec(line);
      if (heading) {
        flushParagraph();
        flushList();
        html.push(`<h${heading[1].length}>${this.inline(heading[2])}</h${heading[1].length}>`);
        continue;
      }
      if (/^\s*---\s*$/.test(line)) {
        flushParagraph();
        flushList();
        html.push('<hr>');
        continue;
      }
      const item = /^\s*([-*]|\d+\.)\s+(.+)$/.exec(line);
      if (item) {
        flushParagraph();
        const ordered = /\d/.test(item[1]);
        if (!list || list.ordered !== ordered) {
          flushList();
          list = { ordered, items: [] };
        }
        list.items.push(item[2]);
        continue;
      }
      const quote = /^&gt;\s?(.*)$/.exec(line);
      if (quote) {
        flushParagraph();
        flushList();
        html.push(`<blockquote>${this.inline(quote[1])}</blockquote>`);
        continue;
      }
      if (!line.trim()) {
        flushParagraph();
        flushList();
        continue;
      }
      const embed = this.embed(line.replace(/&amp;/g, '&'));
      if (embed) {
        flushParagraph();
        flushList();
        html.push(embed);
        continue;
      }
      flushList();
      paragraph.push(line);
    }
    if (fence) html.push(this.fence(fence.lines.join('\n'), fence.language));
    flushParagraph();
    flushList();
    return html.join('\n');
  }

  /**
   * The plain text the rendered HTML shows, block boundaries as newlines —
   * the projection copy and the index read. It must equal the rendered
   * row's innerText, so it walks the same subset the same way.
   */
  static plain(markdown: string): string {
    return markdown
      .replace(/\r\n/g, '\n')
      .replace(/^```[^\n]*\n?/gm, '')
      .replace(/!\[([^\]]*)\]\([^)\s]+\)/g, '$1')
      .replace(/\[([^\]]+)\]\([^)\s]+\)/g, '$1')
      .replace(/(\*\*|__)(.+?)\1/g, '$2')
      .replace(/(^|[^*\w])[*_]([^*_\n]+)[*_](?=[^*\w]|$)/g, '$1$2')
      .replace(/`([^`]+)`/g, '$1')
      .replace(/^#{1,6}\s+/gm, '')
      .replace(/^&gt;\s?|^>\s?/gm, '')
      .replace(/^\s*---\s*$/gm, '')
      .trim();
  }
}

export namespace Markdown {
  export const $Class = Static($Markdown);
  export let Class = $Class;
}

import { Static } from '../../Static';

// Syntax colour for the code a chat shows — tool inputs, outputs, diffs,
// fenced blocks — through shiki, loaded once and only when the first
// block asks for it. Every result is cached by code and language, so a
// row that scrolls out and back never pays twice. Where shiki cannot be
// resolved (the playground on its own), the block stays plain and
// escaped: the page never waits on colour.
class $Highlighter {
  static readonly LANGUAGES = ['bash', 'typescript', 'javascript', 'json', 'vue', 'markdown', 'diff', 'python', 'html', 'css', 'sql', 'yaml', 'jsonc', 'tsx'];
  static readonly ALIASES: Record<string, string> = { sh: 'bash', shell: 'bash', zsh: 'bash', ts: 'typescript', js: 'javascript', mjs: 'javascript', cjs: 'javascript', md: 'markdown', py: 'python', yml: 'yaml', htm: 'html', txt: 'text', text: 'text', log: 'text', '': 'text' };
  static readonly MAXIMUM_CHARS = 40_000;

  /** the shiki module, loading; null once loading failed */
  protected static get $engine(): Promise<Highlighter.Engine | null> {
    return this.load();
  }

  protected static get $cache(): Map<string, string> {
    return new Map();
  }

  static async load(): Promise<Highlighter.Engine | null> {
    try {
      const shiki = (await import('shiki')) as unknown as Highlighter.Shiki;
      const highlighter = await shiki.createHighlighter({ themes: ['github-light', 'one-dark-pro'], langs: this.LANGUAGES });
      return { highlighter, loaded: new Set(this.LANGUAGES) };
    } catch {
      return null;
    }
  }

  /** the language shiki knows for a fence tag or a file extension */
  static language(tag: string): string {
    const lower = tag.toLowerCase();
    const alias = this.ALIASES[lower];
    if (alias) return alias;
    return this.LANGUAGES.includes(lower) ? lower : 'text';
  }

  static languageForPath(path: string): string {
    const extension = path.split('.').pop()?.toLowerCase() ?? '';
    return this.language(extension);
  }

  static escape(code: string): string {
    return code.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  }

  /** plain, escaped — the synchronous first paint and the fallback */
  static plain(code: string): string {
    return `<pre class="chat-code"><code>${this.escape(code)}</code></pre>`;
  }

  /** highlighted HTML with both themes as CSS variables, or the plain form when colour is unavailable */
  static async highlight(code: string, tag: string): Promise<string> {
    const language = this.language(tag);
    if (language === 'text' || code.length > this.MAXIMUM_CHARS) return this.plain(code);
    const key = `${language}�${code}`;
    const cached = this.$cache.get(key);
    if (cached) return cached;
    const engine = await this.$engine;
    if (!engine) return this.plain(code);
    try {
      const html = engine.highlighter.codeToHtml(code, {
        lang: language,
        themes: { light: 'github-light', dark: 'one-dark-pro' },
        defaultColor: false,
      });
      const output = html.replace(/^<pre([^>]*)class="shiki/, '<pre$1class="chat-code shiki');
      this.$cache.set(key, output);
      return output;
    } catch {
      return this.plain(code);
    }
  }
}

export namespace Highlighter {
  export const $Class = Static($Highlighter);
  export let Class = $Class;

  export interface Engine {
    highlighter: { codeToHtml(code: string, options: { lang: string; themes: { light: string; dark: string }; defaultColor: false }): string };
    loaded: Set<string>;
  }

  export interface Shiki {
    createHighlighter(options: { themes: string[]; langs: string[] }): Promise<Engine['highlighter']>;
  }
}

import { ref } from 'vue';
import { Reactive } from '../../ivue';
import { Static } from '../../Static';

// The one clock every waiting thing reads. A loader's elapsed label is a
// plain getter over `now` minus its start, so a thousand pending rows
// cost one interval — and that interval runs only while something is
// pending: `hold()` starts it, the matching `release()` stops it when the
// last holder lets go. Nothing here ticks after its part is done.
class $Clock {
  static readonly TICK_MS = 250;

  /** The one cast per class: instance code reads its own statics here. */
  protected get self() {
    return this.constructor as typeof $Clock;
  }

  /** epoch milliseconds, advanced by the interval while anything holds the clock */
  get now() {
    return ref(Date.now());
  }

  get holders() {
    return ref(0);
  }

  get timer() {
    return ref<ReturnType<typeof setInterval> | null>(null);
  }

  get isTicking(): boolean {
    return this.timer.value !== null;
  }

  /** a pending thing asks the clock to run; returns the release */
  hold(): () => void {
    this.holders.value++;
    if (this.timer.value === null) {
      this.now.value = Date.now();
      this.timer.value = setInterval(() => this.tick(), this.self.TICK_MS);
    }
    let released = false;
    return () => {
      if (released) return;
      released = true;
      this.release();
    };
  }

  release() {
    this.holders.value = Math.max(0, this.holders.value - 1);
    if (this.holders.value === 0 && this.timer.value !== null) {
      clearInterval(this.timer.value);
      this.timer.value = null;
      this.now.value = Date.now();
    }
  }

  tick() {
    this.now.value = Date.now();
  }

  /** elapsed since a start, or the frozen duration once the thing is done */
  elapsed(startedAt: number, durationMs: number | null): number {
    if (durationMs !== null) return durationMs;
    return Math.max(0, this.now.value - startedAt);
  }

  /** "1s", "47s", "1m 04s" — the counter's face; sub-second reads as 0s while live */
  static label(ms: number, live = false): string {
    if (live && ms < 1000) return '0s';
    if (ms < 1000) return `${Math.round(ms)}ms`;
    const seconds = Math.floor(ms / 1000);
    if (seconds < 60) return `${live ? seconds : (ms / 1000).toFixed(seconds < 10 ? 1 : 0)}s`;
    const minutes = Math.floor(seconds / 60);
    if (minutes < 60) return `${minutes}m ${String(seconds % 60).padStart(2, '0')}s`;
    return `${Math.floor(minutes / 60)}h ${String(minutes % 60).padStart(2, '0')}m`;
  }

  dispose() {
    if (this.timer.value !== null) clearInterval(this.timer.value);
    this.timer.value = null;
    this.holders.value = 0;
    this.$stopEffects();
  }
}

export namespace Clock {
  export const $Class = Static($Clock);
  export let Class = Reactive($Class);
  export type Instance = typeof Class.Instance;
  export type Model = InstanceType<typeof Class>;
}

